enc = bytes.fromhex('60 20 f9 be 3b d3 42 f6 94 37 b5 66 f4 65 11 ad 24 d5 7c 21 eb 2b 7b 4b d6')
# algorithm: start edx=0x26; for i=0..24: edx += byte; compare (edx ^ byte) to enc[i]
# so enc[i] = (edx ^ c) & 0xff where edx updates with c before xor.
# Let s0=0x26. For i: s_{i+1}=s_i + c_i (mod 256). enc_i = s_{i+1} ^ c_i = s_i + c_i ^ c_i
# Solve: given s_i and enc_i, find c_i such that (s_i + c_i) ^ c_i == enc_i (mod 256)

sol=[]
s=0x26
for i,e in enumerate(enc):
    candidates=[]
    for c in range(256):
        if ((s + c) & 0xff) ^ c == e:
            candidates.append(c)
    sol.append(candidates)
    print(i,hex(s),hex(e),'#cand',len(candidates), candidates[:10])
    if len(candidates)==1:
        s=(s + candidates[0]) & 0xff
    else:
        # pick arbitrary for now
        if not candidates:
            raise SystemExit('no cand')
        s=(s + candidates[0]) & 0xff

# now choose unique path via backtracking to get printable maybe
from functools import lru_cache

@lru_cache(None)
def dfs(i,s):
    if i==len(enc):
        return b''
    e=enc[i]
    for c in range(256):
        if (((s+c)&0xff) ^ c) == e:
            rest=dfs(i+1,(s+c)&0xff)
            if rest is not None:
                return bytes([c]) + rest
    return None

res=dfs(0,0x26)
print('res',res)
print('as_ascii',res.decode('latin1'))
print('printable_ratio',sum(32<=b<127 for b in res)/len(res))
